function isTimeInterval(
  value: unknown
): value is TimeInterval {
  if (!value || typeof value !== "object") return false;

  const interval = value as Record<string, unknown>;

  return (
    typeof interval.start === "string" &&
    typeof interval.end === "string"
  );
}

function isWeeklyIntervals(
  value: unknown
): value is Record<Weekday, TimeInterval[]> {
  if (!value || typeof value !== "object") return false;

  const intervalsByDay = value as Record<string, unknown>;

  return WEEKDAYS.every((weekday) => {
    const intervals = intervalsByDay[weekday];

    return (
      Array.isArray(intervals) &&
      intervals.every(isTimeInterval)
    );
  });
}

function isOperatingException(
  value: unknown
): value is OperatingHoursException {
  if (!value || typeof value !== "object") return false;

  const exception = value as Record<string, unknown>;

  return (
    typeof exception.date === "string" &&
    Array.isArray(exception.intervals) &&
    exception.intervals.every(isTimeInterval)
  );
}

function isAvailabilityException(
  value: unknown
): value is AvailabilityException {
  return isOperatingException(value);
}

function isPerson(value: unknown): value is Person {
  if (!value || typeof value !== "object") return false;

  const person = value as Record<string, unknown>;

  return (
    typeof person.id === "string" &&
    typeof person.name === "string" &&
    typeof person.active === "boolean" &&
    (person.weeklyContractMinutes === undefined ||
      (typeof person.weeklyContractMinutes === "number" &&
        Number.isSafeInteger(person.weeklyContractMinutes) &&
        person.weeklyContractMinutes >= 0 &&
        person.weeklyContractMinutes <= 10080 &&
        person.weeklyContractMinutes % 15 === 0)) &&
    (person.weeklyTargetMinutes === undefined ||
      (typeof person.weeklyTargetMinutes === "number" &&
        Number.isSafeInteger(person.weeklyTargetMinutes) &&
        person.weeklyTargetMinutes >= 0 &&
        person.weeklyTargetMinutes <= 10080 &&
        person.weeklyTargetMinutes % 15 === 0)) &&
    (person.weeklyContractMinutes === undefined ||
      person.weeklyTargetMinutes === undefined ||
      (typeof person.weeklyTargetMinutes === "number" &&
        typeof person.weeklyContractMinutes === "number" &&
        person.weeklyTargetMinutes <= person.weeklyContractMinutes)) &&
    (person.requiredWorkDates === undefined ||
      (Array.isArray(person.requiredWorkDates) &&
        person.requiredWorkDates.every((date: unknown) => {
          if (typeof date !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(date)) return false;
          const stamp = Date.parse(date + "T00:00:00Z");
          return Number.isFinite(stamp) &&
            new Date(stamp).toISOString().slice(0,10) === date;
        }) &&
        new Set(person.requiredWorkDates).size === person.requiredWorkDates.length)) &&
    (person.unavailableWorkDates === undefined ||
      (Array.isArray(person.unavailableWorkDates) &&
        person.unavailableWorkDates.every((date: unknown) => {
          if (typeof date !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(date)) return false;
          const stamp=Date.parse(date+"T00:00:00Z");
          return Number.isFinite(stamp) &&
            new Date(stamp).toISOString().slice(0,10)===date;
        }) &&
        new Set(person.unavailableWorkDates).size===person.unavailableWorkDates.length &&
        (person.requiredWorkDates===undefined ||
         (Array.isArray(person.requiredWorkDates) &&
          !person.unavailableWorkDates.some((date: string)=>
            (person.requiredWorkDates as string[]).includes(date)))))) &&
    (person.qualificationTags===undefined ||
      (Array.isArray(person.qualificationTags) &&
        person.qualificationTags.every((tag:unknown)=>
          typeof tag==="string" && tag.trim().length>0 &&
          tag.length<=64 && /^[\p{L}\p{N} -]+$/u.test(tag)) &&
        new Set(person.qualificationTags).size===person.qualificationTags.length))
  );
}

function isPersonAvailability(
  value: unknown
): value is PersonAvailability {
  if (!value || typeof value !== "object") return false;

  const availability = value as Record<string, unknown>;

  return (
    typeof availability.personId === "string" &&
    isWeeklyIntervals(availability.weeklyAvailability) &&
    Array.isArray(availability.exceptions) &&
    availability.exceptions.every(isAvailabilityException)
  );
}

function isWorkRulesConfiguration(
  value: unknown
): value is WorkRulesConfiguration {
  if (!value || typeof value !== "object") return false;

  const workRules = value as Record<string, unknown>;
  const duration =
    workRules.standardShiftDurationMinutes;

  const maximum = workRules.maximumDailyEffectiveMinutes;
  const shortDay = workRules.fullShortDayMaximumMinutes;
  const mandatory = workRules.requireShiftsOnAvailableDays;
  return (mandatory === undefined || typeof mandatory === "boolean") &&
    (shortDay === undefined || (typeof shortDay === "number" && Number.isInteger(shortDay) && shortDay>=0 && shortDay<=1440)) &&
    (maximum === undefined ||
    (typeof maximum === "number" && Number.isInteger(maximum) &&
      maximum >= 15 && maximum <= 1440)) && (
    duration === null ||
    (
      typeof duration === "number" &&
      Number.isInteger(duration) &&
      duration > 0
    )
  );
}

function isPresenceRequirement(
  value: unknown
): value is PresenceRequirement {
  if (!value || typeof value !== "object") return false;
  const requirement = value as Record<string, unknown>;
  return (
    typeof requirement.minimumDuringOperation === "number" &&
    typeof requirement.minimumAtOpening === "number" &&
    typeof requirement.minimumAtClosing === "number" &&
    isPresenceRequirementValid(requirement as unknown as PresenceRequirement)
  );
}

function isWeeklyPresenceRequirements(
  value: unknown
): value is WeeklyPresenceRequirements {
  if (!value || typeof value !== "object") return false;
  const weekly = value as Record<string, unknown>;
  return WEEKDAYS.every(
    (day) => weekly[day] === null || isPresenceRequirement(weekly[day])
  );
}

function isPresenceException(value: unknown): value is PresenceException {
  if (!value || typeof value !== "object") return false;
  const exception = value as Record<string, unknown>;
  return (
    typeof exception.date === "string" &&
    (exception.requirements === null ||
      isPresenceRequirement(exception.requirements))
  );
}

function isLegacyAppStateV1(
  value: unknown
): value is LegacyAppStateV1 {
  if (!value || typeof value !== "object") return false;

  const state = value as Record<string, unknown>;

  return (
    state.version === 1 &&
    isWeeklyIntervals(state.weeklyOperatingHours) &&
    Array.isArray(state.exceptions) &&
    state.exceptions.every(isOperatingException) &&
    Array.isArray(state.people) &&
    state.people.every(isPerson)
  );
}

function isLegacyAppStateV2(
  value: unknown
): value is LegacyAppStateV2 {
  if (!value || typeof value !== "object") return false;

  const state = value as Record<string, unknown>;

  return (
    state.version === 2 &&
    isWeeklyIntervals(state.weeklyOperatingHours) &&
    Array.isArray(state.exceptions) &&
    state.exceptions.every(isOperatingException) &&
    Array.isArray(state.people) &&
    state.people.every(isPerson) &&
    Array.isArray(state.availabilities) &&
    state.availabilities.every(isPersonAvailability)
  );
}

function isLegacyAppStateV3(value: unknown): value is LegacyAppStateV3 {
  if (!value || typeof value !== "object") return false;
  const state = value as Record<string, unknown>;
  return (
    state.version === 3 &&
    isWeeklyIntervals(state.weeklyOperatingHours) &&
    Array.isArray(state.exceptions) &&
    state.exceptions.every(isOperatingException) &&
    Array.isArray(state.people) &&
    state.people.every(isPerson) &&
    Array.isArray(state.availabilities) &&
    state.availabilities.every(isPersonAvailability) &&
    isWorkRulesConfiguration(state.workRules)
  );
}

export function isPersistedAppState(
  value: unknown
): value is PersistedAppState {
  if (!value || typeof value !== "object") return false;

  const state = value as Record<string, unknown>;

  return (
    state.version === APP_STATE_VERSION &&
    (state.operationTimeZone === undefined || (
      typeof state.operationTimeZone === "string" &&
      (() => { try {
        new Intl.DateTimeFormat("en", {timeZone: state.operationTimeZone as string});
        return true;
      } catch { return false; } })()
    )) &&
    (state.cycleAnchorDate === undefined || (
      typeof state.cycleAnchorDate === "string" &&
      /^\d{4}-\d{2}-\d{2}$/.test(state.cycleAnchorDate) &&
      Number.isFinite(Date.parse(state.cycleAnchorDate + "T00:00:00Z")) &&
      new Date(state.cycleAnchorDate + "T00:00:00Z").toISOString().slice(0,10) === state.cycleAnchorDate
    )) &&
    isWeeklyIntervals(state.weeklyOperatingHours) &&
    Array.isArray(state.exceptions) &&
    state.exceptions.every(isOperatingException) &&
    Array.isArray(state.people) &&
    state.people.every(isPerson) &&
    Array.isArray(state.availabilities) &&
    state.availabilities.every(isPersonAvailability) &&
    isWorkRulesConfiguration(state.workRules) &&
    isWeeklyPresenceRequirements(state.weeklyPresenceRequirements) &&
    Array.isArray(state.presenceExceptions) &&
    state.presenceExceptions.every(isPresenceException)
  );
}

function emptyWeeklyAvailability(): WeeklyAvailability {
  return WEEKDAYS.reduce(
    (availability, weekday) => {
      availability[weekday] = [];
      return availability;
    },
    {} as WeeklyAvailability
  );
}

function emptyWorkRules(): WorkRulesConfiguration {
  return {
    standardShiftDurationMinutes: null,
  };
}

function migrateV1(
  state: LegacyAppStateV1
): PersistedAppState {
  return {
    version: APP_STATE_VERSION,
    weeklyOperatingHours: state.weeklyOperatingHours,
    exceptions: state.exceptions,
    people: state.people,
    availabilities: state.people.map((person) => ({
      personId: person.id,
      weeklyAvailability: emptyWeeklyAvailability(),
      exceptions: [],
    })),
    workRules: emptyWorkRules(),
    weeklyPresenceRequirements: createEmptyWeeklyPresenceRequirements(),
    presenceExceptions: [],
  };
}

function migrateV2(
  state: LegacyAppStateV2
): PersistedAppState {
  return {
    version: APP_STATE_VERSION,
    weeklyOperatingHours: state.weeklyOperatingHours,
    exceptions: state.exceptions,
    people: state.people,
    availabilities: state.availabilities,
    workRules: emptyWorkRules(),
    weeklyPresenceRequirements: createEmptyWeeklyPresenceRequirements(),
    presenceExceptions: [],
  };
}

function migrateV3(state: LegacyAppStateV3): PersistedAppState {
  return {
    ...state,
    version: APP_STATE_VERSION,
    weeklyPresenceRequirements: createEmptyWeeklyPresenceRequirements(),
    presenceExceptions: [],
  };
}

function parseJson(raw: string): unknown {
  try {
    return JSON.parse(raw) as unknown;
  } catch {
    return null;
  }
}

/**
 * Keep the previous full state before replacing it. In particular, the
 * last state containing people survives any later edits with zero people.
 * A failed backup must abort the write instead of silently losing data.
 */
function backupPreviousState(storage: KeyValueStorage, raw: string): void {
  const previous = parseJson(raw);
  storage.setItem(BACKUP_LATEST_STORAGE_KEY, raw);

  if (
    previous &&
    typeof previous === "object" &&
    Array.isArray((previous as { people?: unknown }).people) &&
    (previous as { people: unknown[] }).people.length > 0
  ) {
    storage.setItem(BACKUP_PEOPLE_STORAGE_KEY, raw);
  }
}

function throwIncompatibleState(raw: string): never {
  const parsed = parseJson(raw);
  const version = parsed && typeof parsed === "object" &&
    "version" in parsed ? String(parsed.version) : "desconhecida";

  throw new Error(
    `Estado guardado incompatível ou inválido (versão ${version}). ` +
    "Os dados foram preservados; a gravação automática está bloqueada."
  );
}

export function createLocalStorageStateRepository(
  storage: KeyValueStorage
): StateRepository {
  let lastObservedRaw: string | null | undefined;

  return {
    async load() {
      const currentRaw = storage.getItem(LOCAL_STORAGE_KEY);

      if (currentRaw !== null) {
        const parsed = parseJson(currentRaw);

        if (isPersistedAppState(parsed)) {
          lastObservedRaw = currentRaw;
          return parsed;
        }

        if (isLegacyAppStateV3(parsed)) {
          const migrated = migrateV3(parsed);
          const migratedRaw = JSON.stringify(migrated);

          backupPreviousState(storage, currentRaw);
          storage.setItem(LOCAL_STORAGE_KEY, migratedRaw);
          lastObservedRaw = migratedRaw;

          return migrated;
        }

        if (isLegacyAppStateV2(parsed)) {
          const migrated = migrateV2(parsed);
          const migratedRaw = JSON.stringify(migrated);

          backupPreviousState(storage, currentRaw);
          storage.setItem(LOCAL_STORAGE_KEY, migratedRaw);
          lastObservedRaw = migratedRaw;

          return migrated;
        }

        throwIncompatibleState(currentRaw);
      }

      const legacyRaw = storage.getItem(LEGACY_LOCAL_STORAGE_KEY_V1);

      if (legacyRaw !== null) {
        const legacy = parseJson(legacyRaw);

        if (!isLegacyAppStateV1(legacy)) {
          throwIncompatibleState(legacyRaw);
        }

        const migrated = migrateV1(legacy);
        const migratedRaw = JSON.stringify(migrated);

        backupPreviousState(storage, legacyRaw);
        storage.setItem(LOCAL_STORAGE_KEY, migratedRaw);
        lastObservedRaw = migratedRaw;

        return migrated;
      }

      lastObservedRaw = null;
      return null;
    },

    async save(state) {
      const currentRaw = storage.getItem(LOCAL_STORAGE_KEY);

      if (
        lastObservedRaw !== undefined &&
        currentRaw !== lastObservedRaw
      ) {
        throw new Error(
          "Os dados guardados foram alterados por outra janela ou versão. " +
          "A gravação foi bloqueada para evitar perdas."
        );
      }

      if (lastObservedRaw === undefined && currentRaw !== null) {
        throw new Error(
          "É necessário carregar os dados guardados antes de os alterar."
        );
      }

      if (currentRaw !== null) {
        const current = parseJson(currentRaw);

        if (!isPersistedAppState(current)) {
          throwIncompatibleState(currentRaw);
        }

        if (current.people.length > 0 && state.people.length === 0) {
          throw new Error(
            "A gravação foi bloqueada: iria apagar os colaboradores existentes."
          );
        }
      }

      const nextRaw = JSON.stringify(state);

      if (nextRaw === currentRaw) {
        return;
      }

      if (currentRaw !== null) {
        backupPreviousState(storage, currentRaw);
      }

      storage.setItem(LOCAL_STORAGE_KEY, nextRaw);
      lastObservedRaw = nextRaw;
    },
  };
}

import type { WorkConstraintConfiguration } from "../types.ts";
import type {
  ConfirmedExternalWorkContext,
} from "./constrainedPeriodGenerator.ts";
import {
  validateWorkConstraints,
  type WorkValidationDateRange,
} from "./workConstraints.ts";

/**
 * The current application stores CONFIGURATION, not approved shifts.
 * It must never interpret missing shift persistence as "no assigned work".
 *
 * This minimal UI adapter only supports a narrowly declared scenario:
 * the operator explicitly confirms that NO OTHER shifts exist outside the
 * target period over the full context needed for weekly/rest rules.
 *
 * A future provider of known external shifts should replace this adapter;
 * the scheduling engine itself already accepts real external assignments.
 */
export interface EmptyExternalContextDeclaration
  extends WorkValidationDateRange {
  timeZone: string;
  rules: WorkConstraintConfiguration;
  confirmedNoExternalShifts: boolean;
}

export interface EmptyContextPreparation {
  status: "ready" | "requires_confirmation" | "invalid_input";
  requiredContext: WorkValidationDateRange | null;
  externalContext: ConfirmedExternalWorkContext | null;
  issues: string[];
}

export function prepareExplicitEmptyContext(
  input: EmptyExternalContextDeclaration
): EmptyContextPreparation {
  const result = validateWorkConstraints({
    timeZone: input.timeZone,
    rules: input.rules,
    targetPeriod: {
      startDate: input.startDate,
      endDate: input.endDate,
    },
    // Explicitly INCOMPLETE: this probe merely determines the exact
    // required date range and checks rules, dates and the IANA zone.
    knownSchedule: {
      startDate: input.startDate,
      endDate: input.endDate,
      complete: false,
      shifts: [],
    },
  });

  if (result.status === "invalid_input" || !result.requiredContext) {
    return {
      status: "invalid_input",
      requiredContext: null,
      externalContext: null,
      issues: result.issues.length
        ? result.issues
        : ["Não foi possível determinar o contexto obrigatório."],
    };
  }

  if (!input.confirmedNoExternalShifts) {
    return {
      status: "requires_confirmation",
      requiredContext: result.requiredContext,
      externalContext: null,
      issues: [
        "O motor não conhece turnos já atribuídos fora do período. "
          + "Não é possível certificar o horário sem confirmar o contexto.",
      ],
    };
  }

  return {
    status: "ready",
    requiredContext: result.requiredContext,
    externalContext: {
      ...result.requiredContext,
      completeOutsideTarget: true,
      shifts: [],
    },
    issues: [],
  };
}
